<section class="page-hero compact"><div class="container"><span class="eyebrow">Account Management</span><h1>My Profile</h1></div></section>
<section class="section container"><div class="profile-card"><div class="profile-avatar"><?php if($user['profile_image']): ?><img src="<?= e($user['profile_image']) ?>" alt="Profile image"><?php else: ?><?= e(strtoupper(substr($user['name'],0,1))) ?><?php endif; ?></div><div class="profile-info"><h2><?= e($user['name']) ?></h2><p><?= e($user['email']) ?></p><div class="pill-row"><span class="role-pill"><?= e(ucfirst($user['role_name'])) ?></span><?= (int)$user['is_verified']===1?'<span class="verified-pill">Verified</span>':'<span class="pending-pill">Pending verification</span>' ?></div><p class="muted">Member since <?= e(date('d M Y',strtotime($user['created_at']))) ?></p></div><div><a class="btn btn-primary" href="<?= e(url('profile/edit')) ?>">Edit Profile / Password</a></div></div></section>
